-- Ширинихои Анас (Shirinihoi Anas, Dushanbe) -- demo data warehouse of a confectionery producer and retail chain in Tajikistan
-- FICTIONAL DATA generated for BI dashboard demos. Currency: TJS (somoni). Period: 2023-01-01 .. 2026-09-30.
-- No public information about the company was found: the profile (central workshop, 10 own points of sale in Dushanbe, Khujand, Bokhtar, Kulob,
-- Istaravshan and Tursunzoda, wholesale and wedding/feast orders) is an assumption; products are traditional Tajik and classic sweets,
-- names are given in Tajik (Cyrillic) and Russian; customers, people, prices and all numbers are invented.
-- Schema is intentionally different from fatir_agro.sql, khimus.sql and kompozit_group.sql: this is a star-schema data warehouse
-- (dim_* / fact_* / bridge_*) with a Tajik-language calendar dimension, daily POS aggregates, online and wholesale orders, write-offs and reviews.
-- Safe to import into an empty MySQL 8 schema.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;


DROP TABLE IF EXISTS `fact_review`;
DROP TABLE IF EXISTS `fact_store_expense`;
DROP TABLE IF EXISTS `fact_custom_order`;
DROP TABLE IF EXISTS `fact_wholesale_order_line`;
DROP TABLE IF EXISTS `fact_wholesale_order`;
DROP TABLE IF EXISTS `dim_wholesale_client`;
DROP TABLE IF EXISTS `fact_online_order_line`;
DROP TABLE IF EXISTS `fact_online_order`;
DROP TABLE IF EXISTS `fact_writeoff`;
DROP TABLE IF EXISTS `fact_sales_daily`;
DROP TABLE IF EXISTS `dim_calendar_event`;
DROP TABLE IF EXISTS `dim_promotion`;
DROP TABLE IF EXISTS `dim_loyalty_card`;
DROP TABLE IF EXISTS `fact_production`;
DROP TABLE IF EXISTS `fact_purchase`;
DROP TABLE IF EXISTS `dim_supplier`;
DROP TABLE IF EXISTS `bridge_recipe`;
DROP TABLE IF EXISTS `dim_ingredient`;
DROP TABLE IF EXISTS `fact_price_change`;
DROP TABLE IF EXISTS `dim_product`;
DROP TABLE IF EXISTS `dim_product_group`;
DROP TABLE IF EXISTS `dim_employee`;
DROP TABLE IF EXISTS `dim_store`;
DROP TABLE IF EXISTS `dim_city`;
DROP TABLE IF EXISTS `dim_date`;

CREATE TABLE `dim_date` (
    `date_value` DATE NOT NULL,
    `year_no` SMALLINT NOT NULL,
    `quarter_no` TINYINT NOT NULL,
    `month_no` TINYINT NOT NULL,
    `month_name_tj` VARCHAR(12) NOT NULL,
    `month_name_ru` VARCHAR(12) NOT NULL,
    `weekday_no` TINYINT NOT NULL,
    `weekday_name_tj` VARCHAR(12) NOT NULL,
    `is_weekend` TINYINT(1) NOT NULL,
    `is_ramadan` TINYINT(1) NOT NULL,
    `is_wedding_season` TINYINT(1) NOT NULL,
    PRIMARY KEY (`date_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Тақвим (бо номҳои тоҷикӣ) / Календарь';

CREATE TABLE `dim_city` (
    `city_id` TINYINT UNSIGNED NOT NULL,
    `name_ru` VARCHAR(40) NOT NULL,
    `name_tj` VARCHAR(40) NOT NULL,
    `region_tj` VARCHAR(60) NOT NULL,
    `latitude` DECIMAL(9,6) NOT NULL,
    `longitude` DECIMAL(9,6) NOT NULL,
    PRIMARY KEY (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Шаҳрҳо / Города';

CREATE TABLE `dim_store` (
    `store_code` CHAR(3) NOT NULL,
    `store_name` VARCHAR(80) NOT NULL,
    `city_id` TINYINT UNSIGNED NOT NULL,
    `format` ENUM('flagship','store','mall_point','kiosk','cafe') NOT NULL,
    `address_tj` VARCHAR(120) NOT NULL,
    `latitude` DECIMAL(9,6) NOT NULL,
    `longitude` DECIMAL(9,6) NOT NULL,
    `area_m2` SMALLINT UNSIGNED NOT NULL,
    `opened_on` DATE NOT NULL,
    `closed_on` DATE NULL,
    PRIMARY KEY (`store_code`),
    CONSTRAINT `fk_store_city` FOREIGN KEY (`city_id`) REFERENCES `dim_city` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Дӯконҳо / Магазины';

CREATE TABLE `dim_employee` (
    `staff_id` SMALLINT UNSIGNED NOT NULL,
    `full_name` VARCHAR(80) NOT NULL,
    `gender` CHAR(1) NOT NULL,
    `role` ENUM('manager','seller','cashier','confectioner','baker_helper','courier','driver','accountant','technologist') NOT NULL,
    `store_code` CHAR(3) NULL,
    `hired_on` DATE NOT NULL,
    `terminated_on` DATE NULL,
    `monthly_salary_tjs` DECIMAL(9,2) NOT NULL,
    `phone` VARCHAR(20) NOT NULL,
    PRIMARY KEY (`staff_id`),
    KEY `ix_staff_store` (`store_code`),
    CONSTRAINT `fk_staff_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Кормандон / Сотрудники';

CREATE TABLE `dim_product_group` (
    `group_id` TINYINT UNSIGNED NOT NULL,
    `name_ru` VARCHAR(60) NOT NULL,
    `name_tj` VARCHAR(60) NOT NULL,
    `is_fresh` TINYINT(1) NOT NULL,
    PRIMARY KEY (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Гурӯҳҳои маҳсулот / Группы продукции';

CREATE TABLE `dim_product` (
    `sku` CHAR(7) NOT NULL,
    `group_id` TINYINT UNSIGNED NOT NULL,
    `name_ru` VARCHAR(100) NOT NULL,
    `name_tj` VARCHAR(100) NOT NULL,
    `unit` ENUM('kg','pcs','box') NOT NULL,
    `unit_weight_kg` DECIMAL(6,3) NOT NULL,
    `shelf_life_days` SMALLINT UNSIGNED NOT NULL,
    `season` ENUM('none','navruz','ramadan_eid','new_year','womens_day') NOT NULL,
    `is_halal` TINYINT(1) NOT NULL,
    `unit_cost_tjs` DECIMAL(9,2) NOT NULL,
    `current_price_tjs` DECIMAL(9,2) NOT NULL,
    `launched_on` DATE NOT NULL,
    `discontinued_on` DATE NULL,
    PRIMARY KEY (`sku`),
    KEY `ix_product_group` (`group_id`),
    CONSTRAINT `fk_product_group` FOREIGN KEY (`group_id`) REFERENCES `dim_product_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Маҳсулот / Ассортимент';

CREATE TABLE `fact_price_change` (
    `sku` CHAR(7) NOT NULL,
    `valid_from` DATE NOT NULL,
    `price_tjs` DECIMAL(9,2) NOT NULL,
    PRIMARY KEY (`sku`, `valid_from`),
    CONSTRAINT `fk_price_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Таърихи нархҳо / История цен';

CREATE TABLE `dim_ingredient` (
    `ingredient_id` TINYINT UNSIGNED NOT NULL,
    `name_ru` VARCHAR(60) NOT NULL,
    `name_tj` VARCHAR(60) NOT NULL,
    `category` ENUM('flour','sugar_sweet','dairy_fat','nuts_dried','eggs','flavor','other') NOT NULL,
    `unit` ENUM('kg','l','pcs') NOT NULL,
    `ref_price_tjs` DECIMAL(8,2) NOT NULL,
    PRIMARY KEY (`ingredient_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ашёи хом / Сырьё';

CREATE TABLE `bridge_recipe` (
    `sku` CHAR(7) NOT NULL,
    `ingredient_id` TINYINT UNSIGNED NOT NULL,
    `qty_per_kg` DECIMAL(8,4) NOT NULL,
    PRIMARY KEY (`sku`, `ingredient_id`),
    CONSTRAINT `fk_recipe_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`),
    CONSTRAINT `fk_recipe_ing` FOREIGN KEY (`ingredient_id`) REFERENCES `dim_ingredient` (`ingredient_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рецептура: сарф ба 1 кг маҳсулот';

CREATE TABLE `dim_supplier` (
    `supplier_id` TINYINT UNSIGNED NOT NULL,
    `name` VARCHAR(100) NOT NULL,
    `country` VARCHAR(30) NOT NULL,
    `city` VARCHAR(40) NOT NULL,
    `payment_days` TINYINT UNSIGNED NOT NULL,
    `reliability` DECIMAL(3,1) NOT NULL,
    PRIMARY KEY (`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Таъминкунандагон / Поставщики';

CREATE TABLE `fact_purchase` (
    `purchase_id` INT UNSIGNED NOT NULL,
    `supplier_id` TINYINT UNSIGNED NOT NULL,
    `ingredient_id` TINYINT UNSIGNED NOT NULL,
    `purchase_date` DATE NOT NULL,
    `qty` DECIMAL(10,2) NOT NULL,
    `unit_price_tjs` DECIMAL(8,2) NOT NULL,
    `total_tjs` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`purchase_id`),
    KEY `ix_purch_date` (`purchase_date`),
    CONSTRAINT `fk_purch_sup` FOREIGN KEY (`supplier_id`) REFERENCES `dim_supplier` (`supplier_id`),
    CONSTRAINT `fk_purch_ing` FOREIGN KEY (`ingredient_id`) REFERENCES `dim_ingredient` (`ingredient_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Хариди ашёи хом / Закупки сырья';

CREATE TABLE `fact_production` (
    `batch_id` INT UNSIGNED NOT NULL,
    `batch_date` DATE NOT NULL,
    `sku` CHAR(7) NOT NULL,
    `shift` ENUM('night','morning') NOT NULL,
    `confectioner_id` SMALLINT UNSIGNED NOT NULL,
    `planned_qty` DECIMAL(10,2) NOT NULL,
    `produced_qty` DECIMAL(10,2) NOT NULL,
    `defect_qty` DECIMAL(10,2) NOT NULL,
    `duration_min` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`batch_id`),
    KEY `ix_batch_date` (`batch_date`),
    KEY `ix_batch_sku` (`sku`),
    CONSTRAINT `fk_batch_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`),
    CONSTRAINT `fk_batch_staff` FOREIGN KEY (`confectioner_id`) REFERENCES `dim_employee` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Истеҳсолот дар цехи марказӣ / Партии цеха';

CREATE TABLE `dim_loyalty_card` (
    `card_id` INT UNSIGNED NOT NULL,
    `holder_name` VARCHAR(80) NOT NULL,
    `phone_masked` VARCHAR(20) NOT NULL,
    `joined_on` DATE NOT NULL,
    `home_store` CHAR(3) NOT NULL,
    `tier` ENUM('silver','gold','platinum') NOT NULL,
    `birth_month` TINYINT UNSIGNED NOT NULL,
    `city_id` TINYINT UNSIGNED NOT NULL,
    PRIMARY KEY (`card_id`),
    CONSTRAINT `fk_card_store` FOREIGN KEY (`home_store`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_card_city` FOREIGN KEY (`city_id`) REFERENCES `dim_city` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Корти садоқат / Карты лояльности';

CREATE TABLE `dim_promotion` (
    `promo_id` SMALLINT UNSIGNED NOT NULL,
    `title_tj` VARCHAR(100) NOT NULL,
    `title_ru` VARCHAR(100) NOT NULL,
    `group_id` TINYINT UNSIGNED NULL,
    `start_date` DATE NOT NULL,
    `end_date` DATE NOT NULL,
    `discount_pct` DECIMAL(4,1) NOT NULL,
    PRIMARY KEY (`promo_id`),
    CONSTRAINT `fk_promo_group` FOREIGN KEY (`group_id`) REFERENCES `dim_product_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Аксияҳо / Акции';

CREATE TABLE `dim_calendar_event` (
    `event_date` DATE NOT NULL,
    `name_tj` VARCHAR(80) NOT NULL,
    `name_ru` VARCHAR(80) NOT NULL,
    `kind` ENUM('national','religious','international','wedding_season') NOT NULL,
    `demand_uplift` DECIMAL(3,2) NOT NULL,
    PRIMARY KEY (`event_date`, `name_ru`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рӯйдодҳои тақвим ва ид / Праздники и события';

CREATE TABLE `fact_sales_daily` (
    `sale_date` DATE NOT NULL,
    `store_code` CHAR(3) NOT NULL,
    `sku` CHAR(7) NOT NULL,
    `qty` DECIMAL(9,2) NOT NULL,
    `gross_tjs` DECIMAL(11,2) NOT NULL,
    `discount_tjs` DECIMAL(10,2) NOT NULL,
    `receipts_cnt` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`sale_date`, `store_code`, `sku`),
    KEY `ix_ds_sku` (`sku`),
    KEY `ix_ds_store` (`store_code`),
    CONSTRAINT `fk_ds_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_ds_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Фурӯши рӯзона аз кассаҳо (POS) / Продажи по дням из кассы';

CREATE TABLE `fact_writeoff` (
    `writeoff_id` INT UNSIGNED NOT NULL,
    `writeoff_date` DATE NOT NULL,
    `store_code` CHAR(3) NOT NULL,
    `sku` CHAR(7) NOT NULL,
    `qty` DECIMAL(8,2) NOT NULL,
    `reason` ENUM('expired','damaged','tasting','return_from_client') NOT NULL,
    `cost_tjs` DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (`writeoff_id`),
    KEY `ix_wo_date` (`writeoff_date`),
    CONSTRAINT `fk_wo_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_wo_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Хориҷкунӣ / Списания';

CREATE TABLE `fact_online_order` (
    `order_id` INT UNSIGNED NOT NULL,
    `card_id` INT UNSIGNED NULL,
    `store_code` CHAR(3) NOT NULL,
    `ordered_at` DATETIME NOT NULL,
    `channel` ENUM('telegram','instagram','phone','website') NOT NULL,
    `fulfilment` ENUM('delivery','pickup') NOT NULL,
    `district_tj` VARCHAR(60) NULL,
    `courier_id` SMALLINT UNSIGNED NULL,
    `delivery_fee_tjs` DECIMAL(7,2) NOT NULL,
    `items_total_tjs` DECIMAL(10,2) NOT NULL,
    `payment` ENUM('cash','korti_milli','mobile_wallet','bank_card') NOT NULL,
    `status` ENUM('delivered','cancelled') NOT NULL,
    `delivered_at` DATETIME NULL,
    `rating` TINYINT UNSIGNED NULL,
    PRIMARY KEY (`order_id`),
    KEY `ix_oo_at` (`ordered_at`),
    KEY `ix_oo_card` (`card_id`),
    CONSTRAINT `fk_oo_card` FOREIGN KEY (`card_id`) REFERENCES `dim_loyalty_card` (`card_id`),
    CONSTRAINT `fk_oo_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_oo_courier` FOREIGN KEY (`courier_id`) REFERENCES `dim_employee` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Фармоишҳои онлайн / Онлайн-заказы';

CREATE TABLE `fact_online_order_line` (
    `order_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `sku` CHAR(7) NOT NULL,
    `qty` DECIMAL(8,2) NOT NULL,
    `unit_price_tjs` DECIMAL(9,2) NOT NULL,
    PRIMARY KEY (`order_id`, `line_no`),
    CONSTRAINT `fk_ool_order` FOREIGN KEY (`order_id`) REFERENCES `fact_online_order` (`order_id`),
    CONSTRAINT `fk_ool_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сатрҳои фармоиши онлайн';

CREATE TABLE `dim_wholesale_client` (
    `client_id` SMALLINT UNSIGNED NOT NULL,
    `name` VARCHAR(100) NOT NULL,
    `client_type` ENUM('supermarket','cafe','wedding_hall','distributor','export','corporate') NOT NULL,
    `city_id` TINYINT UNSIGNED NULL,
    `country` VARCHAR(30) NOT NULL,
    `signed_on` DATE NOT NULL,
    `payment_days` TINYINT UNSIGNED NOT NULL,
    `discount_pct` DECIMAL(4,1) NOT NULL,
    PRIMARY KEY (`client_id`),
    CONSTRAINT `fk_wc_city` FOREIGN KEY (`city_id`) REFERENCES `dim_city` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Харидорони улгурҷӣ / Оптовые клиенты';

CREATE TABLE `fact_wholesale_order` (
    `wh_order_id` INT UNSIGNED NOT NULL,
    `client_id` SMALLINT UNSIGNED NOT NULL,
    `order_date` DATE NOT NULL,
    `delivery_date` DATE NOT NULL,
    `event_kind` ENUM('regular','wedding','funeral_memorial','corporate','holiday') NOT NULL,
    `manager_id` SMALLINT UNSIGNED NOT NULL,
    `status` ENUM('delivered','cancelled','open') NOT NULL,
    `total_tjs` DECIMAL(12,2) NOT NULL,
    `paid_tjs` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`wh_order_id`),
    KEY `ix_who_date` (`order_date`),
    CONSTRAINT `fk_who_client` FOREIGN KEY (`client_id`) REFERENCES `dim_wholesale_client` (`client_id`),
    CONSTRAINT `fk_who_mgr` FOREIGN KEY (`manager_id`) REFERENCES `dim_employee` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Фармоишҳои улгурҷӣ / Оптовые заказы';

CREATE TABLE `fact_wholesale_order_line` (
    `wh_order_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `sku` CHAR(7) NOT NULL,
    `qty` DECIMAL(9,2) NOT NULL,
    `unit_price_tjs` DECIMAL(9,2) NOT NULL,
    PRIMARY KEY (`wh_order_id`, `line_no`),
    CONSTRAINT `fk_whl_order` FOREIGN KEY (`wh_order_id`) REFERENCES `fact_wholesale_order` (`wh_order_id`),
    CONSTRAINT `fk_whl_sku` FOREIGN KEY (`sku`) REFERENCES `dim_product` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сатрҳои фармоиши улгурҷӣ';

CREATE TABLE `fact_custom_order` (
    `custom_id` INT UNSIGNED NOT NULL,
    `store_code` CHAR(3) NOT NULL,
    `card_id` INT UNSIGNED NULL,
    `ordered_on` DATE NOT NULL,
    `event_date` DATE NOT NULL,
    `occasion` ENUM('nikoh_toy','birthday','sunnat_toy','jubilee','corporate','khatmi_quron','other') NOT NULL,
    `product_kind` ENUM('cake','sweet_table','gift_boxes','mixed') NOT NULL,
    `guests` SMALLINT UNSIGNED NOT NULL,
    `weight_kg` DECIMAL(6,1) NOT NULL,
    `price_tjs` DECIMAL(10,2) NOT NULL,
    `prepayment_tjs` DECIMAL(10,2) NOT NULL,
    `status` ENUM('completed','cancelled') NOT NULL,
    `note_tj` VARCHAR(160) NULL,
    PRIMARY KEY (`custom_id`),
    KEY `ix_co_event` (`event_date`),
    CONSTRAINT `fk_co_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_co_card` FOREIGN KEY (`card_id`) REFERENCES `dim_loyalty_card` (`card_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Фармоишҳои махсус (тӯй, ҷашн) / Заказы на мероприятия';

CREATE TABLE `fact_store_expense` (
    `period_month` DATE NOT NULL,
    `store_code` CHAR(3) NOT NULL,
    `category` ENUM('rent','payroll','utilities','marketing','packaging','delivery','other') NOT NULL,
    `amount_tjs` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`period_month`, `store_code`, `category`),
    CONSTRAINT `fk_exp_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Хароҷоти дӯконҳо / Расходы магазинов';

CREATE TABLE `fact_review` (
    `review_id` INT UNSIGNED NOT NULL,
    `store_code` CHAR(3) NOT NULL,
    `card_id` INT UNSIGNED NULL,
    `review_date` DATE NOT NULL,
    `source` ENUM('2gis','instagram','telegram','google_maps','book') NOT NULL,
    `rating` TINYINT UNSIGNED NOT NULL,
    `language` ENUM('tj','ru') NOT NULL,
    `review_text` VARCHAR(255) NOT NULL,
    PRIMARY KEY (`review_id`),
    KEY `ix_rev_store` (`store_code`),
    CONSTRAINT `fk_rev_store` FOREIGN KEY (`store_code`) REFERENCES `dim_store` (`store_code`),
    CONSTRAINT `fk_rev_card` FOREIGN KEY (`card_id`) REFERENCES `dim_loyalty_card` (`card_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Назарҳои муштариён / Отзывы';
































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;
